#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>
using namespace std;
int main() {
    vector<pair<int, int>> events;
    events.push_back(make_pair(1, 1));
    events.push_back(make_pair(5, -1));
    sort(events.begin(), events.end());
    int cur = 0, best = 0;
    for (int i = 0; i < 2; i++) {
        cur = cur + events[i].second;
        if (cur > best) best = cur;
    }
    cout << best << endl;
    return 0;
}
